    checklist: ["학년별 적정 시간 정착 (초 30분·중 1시간·고 2시간)?","개념 40% : 풀이 40% : 실험·자료 20% 비율?","4과목 (물·화·생·지) 균형 배분?","스마트폰·SNS 차단 환경?","매일 같은 시간·같은 장소 습관?"],
