      body: "유전·진화는 생명과학에서 출제 비중 25%로 가장 큰 단원이에요. 특히 \"유전 가계도\"는 수능·내신 킬러 문항으로 매년 출제됩니다. \"DNA·유전자 → 멘델 유전 → 사람의 유전 → 진화·자연선택\" 4단계 흐름이 핵심이에요. 단순 암기로는 절대 1·2등급 못 가요. 가계도 분석·확률 계산·DNA 발현 과정을 정확히 이해해야 합니다. 가계도는 \"우열·상/성염색체 판별 → 유전자형 추론 → 확률 계산\" 3단계로 풀어요. 1:1 과외에서 유전 단원은 8~12시간 (가장 긴 시간) 투자 필요. 하지만 유전만 잘 잡으면 생명과학 1·2등급의 절반 확보예요."
