      body: "미생물·면역은 생명과학에서 출제 비중 10%로 작지만, 코로나19 이후 시사적 중요성이 커진 단원이에요. \"미생물 종류 → 감염과 질병 → 면역 체계 → 백신·항생제\" 4단계 흐름이 핵심입니다. 특히 \"비특이적 면역 vs 특이적 면역\"·\"체액성 면역 vs 세포성 면역\"·\"능동 면역 vs 수동 면역\" 비교가 시험 단골이에요. 코로나19 백신·mRNA·변이 같은 시사 자료도 함께 출제됩니다. 단순 암기가 아니라 \"항원-항체 반응\" 메커니즘 이해가 답이에요. 1:1 과외에서 미생물·면역은 4~5시간이면 정복 가능해요. 시각 자료·표 정리가 효율 최대입니다."
