    body: "물리 실전 풀이는 개념 학습을 마친 학생들이 시험에서 1·2등급을 받기 위한 마지막 단계예요. 물리는 다른 과학 분과와 달리 \"수학적 사고·계산 능력\"이 핵심이라 단순 개념 암기로는 절대 1·2등급 못 가요. \"계산 문제 풀이법 → 자료 해석 → 킬러 문항 전략 → 기출 패턴 분석\" 4단계 흐름이 답입니다. 특히 \"v-t·F-t·F-x 그래프\"·\"운동량 보존 충돌\"·\"전자기 유도\"가 매년 킬러 문항으로 출제됩니다. 평가원 5개년 + EBS 수능특강 + 학교 기출 통합 풀이 + 1:1 첨삭이 1·2등급의 비밀이에요. 1:1 과외에서 물리 실전은 8~12시간 (가장 긴 시간) 투자 필요. 물리는 \"양 + 질\"이 모두 답이에요."
